    # Prioritize moving toward nearest resource
    target = None
    min_dist = float('inf')
    for res in resources:
        rx, ry = res
        dist = abs(rx - x) + abs(ry - y)
        if dist < min_dist:
            min_dist = dist
            target = (rx, ry)

    if target:
